// corpus-reader batch-E differential vs pinned NLTK 3.10.3 oracle.
// Synthetic fixtures are generated by test/corpus_readers5_oracle.py.
import { describe, expect, test } from "bun:test";
import { spawnSync } from "node:child_process";
import { mkdirSync } from "node:fs";
import { join } from "node:path";
import {
  PropbankCorpusReader, PropbankInstance, PropbankInflection, PropbankTreePointer,
  NombankCorpusReader, NombankInstance, NombankTreePointer,
  SemcorCorpusReader, SensevalCorpusReader, RTECorpusReader, norm,
} from "../src/corpus_readers5";
import { parseXmlString } from "../src/xmldocs";
import { BracketParseCorpusReader } from "../src/corpus_readers2";
import { FileSystemPathPointer, dataPath } from "../src/data";
import { pyError } from "../src/internals";

const NLTK_DATA = process.env.NLTK_DATA ?? join(process.cwd(), ".cache/nltk-data");
const ROOT = join(NLTK_DATA, "tmp-synth-corpus5");

function setup(): string {
  mkdirSync(ROOT, { recursive: true });
  if (!dataPath.includes(ROOT)) dataPath.push(ROOT);
  return ROOT;
}

function oracle(root: string): Record<string, any> {
  const res = spawnSync("python3", ["test/corpus_readers5_oracle.py", root], { encoding: "utf-8" });
  if (res.status !== 0) throw new Error(`oracle failed: ${res.stderr}`);
  return JSON.parse(res.stdout.trim().split("\n").pop()!);
}

function err<T>(f: () => T): { err: string | null; val?: T } {
  try {
    return { err: null, val: f() };
  } catch (e: any) {
    return { err: `${e.name}:${String(e.message).slice(0, 160)}` };
  }
}

function projTree(t: any): any {
  return { tree: t.pformat(), label: `${t.label}` };
}

function projInst(i: any): any {
  const args = i.arguments.map(([loc, argid]: [any, string]) => {
    const e: any = { loc: `${loc}`, locrepr: loc.repr(), argid };
    if (i.tree !== null) {
      e.sel = projTree(loc.select(i.tree));
      if (loc.treepos) e.treepos = [...loc.treepos(i.tree)];
    }
    return e;
  });
  return {
    repr: i.repr(),
    str: `${i}`,
    fileid: i.fileid,
    sentnum: i.sentnum,
    wordnum: i.wordnum,
    tagger: i.tagger,
    roleset: i.roleset,
    baseform: i.baseform,
    sensenumber: i.sensenumber,
    predid: i.predid,
    inflection: `${i.inflection}`,
    predicate: i.predicate.repr(),
    arguments: args,
    tree: i.tree !== null ? i.tree.pformat() : null,
    pred_sel: projTree(i.predicate.select(i.tree)),
    sel_none: err(() => i.predicate.select(null)),
  };
}

function projNinst(i: any): any {
  const args = i.arguments.map(([loc, argid]: [any, string]) => {
    const e: any = { loc: `${loc}`, locrepr: loc.repr(), argid };
    if (i.tree !== null) e.sel = projTree(loc.select(i.tree));
    return e;
  });
  return {
    repr: i.repr(),
    str: `${i}`,
    fileid: i.fileid,
    sentnum: i.sentnum,
    wordnum: i.wordnum,
    baseform: i.baseform,
    sensenumber: i.sensenumber,
    predid: i.predid,
    roleset: i.roleset,
    predicate: i.predicate.repr(),
    arguments: args,
    tree: i.tree !== null ? i.tree.pformat() : null,
    pred_sel: projTree(i.predicate.select(i.tree)),
  };
}

function projEl(e: any): any {
  if (e?.pformat) return projTree(e);
  if (Array.isArray(e)) return e.map(projEl);
  return e;
}

function projItem(x: any): any {
  if (x?.pformat) return projTree(x);
  if (Array.isArray(x)) return { sent: [...x].map(projEl), num: (x as any).num ?? null };
  return { words: [...x] };
}

const FakeWN = { lemma_from_key: (key: string): never => { throw pyError("KeyError", `'${key}'`); } };

describe("corpus readers batch E vs NLTK 3.10.3 oracle", () => {
  const root = setup();
  const o = oracle(root);
  const pc = new BracketParseCorpusReader(join(ROOT, "mrg"), ".*\\.mrg");
  const xform = (f: string) => f.split("/").pop()!;

  test("PropbankCorpusReader fileids/lines/verbs/instances/rolesets", () => {
    const pb = new PropbankCorpusReader(
      new FileSystemPathPointer(join(ROOT, "propbank")), "wsj.gold",
      "frames/.*\\.xml", "verbs.txt", xform, pc);
    const pb2 = new PropbankCorpusReader(
      new FileSystemPathPointer(join(ROOT, "propbank")), "wsj.gold", "frames/.*\\.xml");
    expect(pb.fileids()).toEqual(o.pb.fileids);
    expect(pb2.fileids()).toEqual(o.pb.pb2_fileids);
    expect([...pb.lines() as Iterable<string>]).toEqual(o.pb.lines);
    expect([...pb.verbs() as Iterable<string>]).toEqual(o.pb.verbs);
    expect(pc.fileids()).toEqual(o.pb.pc_fileids);
    const insts = [...pb.instances() as Iterable<PropbankInstance>].map(projInst);
    expect(insts).toEqual(o.pb.instances);
    expect([...pb.instances("run") as Iterable<PropbankInstance>].map((i) => i.roleset)).toEqual(o.pb.inst_run);
    expect([...pb.instances("sprint") as Iterable<PropbankInstance>].map((i) => i.roleset)).toEqual(o.pb.inst_sprint);
    expect([...pb2.instances() as Iterable<PropbankInstance>][0]!.tree).toBe(o.pb.pb2_tree0 ? null : expect.anything() as any);
  });

  test("PropbankCorpusReader roleset/rolesets + error pins", () => {
    const pb = new PropbankCorpusReader(
      new FileSystemPathPointer(join(ROOT, "propbank")), "wsj.gold",
      "frames/.*\\.xml", "verbs.txt", xform, pc);
    const rs = pb.roleset("run.02");
    expect({
      tag: rs.tag,
      id: rs.attrib.get("id"),
      name: rs.attrib.get("name"),
      children: [...rs.get(0)!].map((ch) => [ch.tag, Object.fromEntries(ch.attrib)]),
    }).toEqual(o.pb.roleset);
    expect(err(() => pb.roleset("jump.01"))).toEqual(o.pb.roleset_err);
    expect(err(() => pb.roleset("run.99"))).toEqual(o.pb.roleset_err2);
    expect([...pb.rolesets() as Iterable<any>].map((r) => r.attrib.get("id"))).toEqual(o.pb.rolesets);
    expect([...pb.rolesets("run") as Iterable<any>].map((r) => r.attrib.get("id"))).toEqual(o.pb.rolesets_run);
    expect(err(() => pb.rolesets("jump"))).toEqual(o.pb.rolesets_err);
  });

  test("PropbankTreePointer parse + PropbankInflection", () => {
    const ptrs = ["3:1*5:0", "1:0,2:1", "x", "1:2:3", ":", "1,a:2"].map((s) =>
      err(() => { const p = PropbankTreePointer.parse(s) as any; return { str: `${p}`, repr: p.repr() }; }));
    expect(ptrs).toEqual(o.pb.ptrs);
    const infl = ["vp--a", "-----", "vn-3a", "vv-p3", "xxxxx", "vp--", null].map((s: any) =>
      err(() => {
        const i = PropbankInflection.parse(s);
        return {
          str: `${i}`, repr: i.repr(), form: i.form, tense: i.tense,
          aspect: i.aspect, person: i.person, voice: i.voice,
        };
      }));
    expect(infl).toEqual(o.pb.infl);
  });

  test("PropbankInstance.parse malformed lines", () => {
    const bad = [
      "wsj_0001.mrg 0 3 gold run.02 vp--a 4:0-rel 5:0-ARG1-extra",
      "wsj_0001.mrg 0 3 gold run.02 vp--a 4:0-rel 5:0-rel",
      "wsj_0001.mrg 0 3 gold run.02 vv-p3 4:0-rel",
      "short",
    ].map((s) => err(() => ({ fileid: PropbankInstance.parse(s, xform).fileid, str: `${PropbankInstance.parse(s, xform)}` })));
    expect(bad).toEqual(o.pb.bad);
    expect(err(() => PropbankInstance.parse("wsj_0001.mrg 0 3 gold run.02 vp--a 4:0-rel 5:0-ARG1-extra").fileid))
      .toEqual(o.pb.bad_noxform);
  });

  test("NombankCorpusReader fileids/lines/nouns/instances/rolesets", () => {
    const nb = new NombankCorpusReader(
      new FileSystemPathPointer(join(ROOT, "nombank")), "nombank.1.0",
      "frames/.*\\.xml", "nombank.1.0.words", xform, pc);
    expect(nb.fileids()).toEqual(o.nb.fileids);
    expect([...nb.lines() as Iterable<string>]).toEqual(o.nb.lines);
    expect([...nb.nouns() as Iterable<string>]).toEqual(o.nb.nouns);
    const insts = [...nb.instances() as Iterable<NombankInstance>].map(projNinst);
    expect(insts).toEqual(o.nb.instances);
    expect([...nb.instances("sale") as Iterable<NombankInstance>].map((i) => i.roleset)).toEqual(o.nb.inst_sale);
    const nrs = nb.roleset("sale.01");
    expect({ tag: nrs.tag, id: nrs.attrib.get("id"), name: nrs.attrib.get("name") }).toEqual(o.nb.roleset);
    expect(err(() => nb.roleset("nosuch.01"))).toEqual(o.nb.roleset_err);
    expect(err(() => nb.roleset("nosuch"))).toEqual(o.nb.roleset_err2);
    expect([...nb.rolesets() as Iterable<any>].map((r) => r.attrib.get("id"))).toEqual(o.nb.rolesets);
    expect(err(() => nb.rolesets("nosuch"))).toEqual(o.nb.rolesets_err);
    expect(err(() => (NombankTreePointer.parse("3:1*5:0") as any).repr())).toEqual(o.nb.ptr);
  });

  test("NombankInstance.parse malformed + roleset normalization", () => {
    const nbBad = [
      "wsj_0001.mrg 0 2 sale 1 2:0-rel 1:0-rel",
      "wsj_0001.mrg 0 2 sale",
      "wsj_0001.mrg 0 2 sale 1 badloc-rel",
      "wsj_0001.mrg 0 2 sale 1 2:0-rel nohyphen",
      "wsj_0001.mrg 0 x sale 1 2:0-rel",
      "f 0 0 sale 1 0:0-relX 1:0-rel",
    ].map((s) => err(() => {
      const i = NombankInstance.parse(s, xform);
      return { str: `${i}`, predid: i.predid, roleset: i.roleset };
    }));
    expect(nbBad).toEqual(o.nb.bad);
    const norms = ["10%", "1/10"].map((b) =>
      err(() => NombankInstance.parse(`f 0 0 ${b} 1 0:0-rel`, (f) => f).roleset));
    expect(norms).toEqual(o.nb.roleset_norm);
  });

  test("SemcorCorpusReader lazy words/chunks/sents/tagged", () => {
    const sc = new SemcorCorpusReader(
      new FileSystemPathPointer(join(ROOT, "semcor")), "sem1\\.xml", FakeWN);
    const sc2 = new SemcorCorpusReader(
      new FileSystemPathPointer(join(ROOT, "semcor")), "sem2\\.xml", FakeWN);
    expect(sc.fileids()).toEqual(o.sc.fileids);
    expect([...sc.words() as Iterable<string>]).toEqual(o.sc.words);
    expect([...sc.words("sem1.xml") as Iterable<string>]).toEqual(o.sc.words_fid);
    expect([...sc.chunks() as Iterable<unknown>].map(projItem)).toEqual(o.sc.chunks);
    expect([...sc.sents() as Iterable<unknown>].map(projItem)).toEqual(o.sc.sents);
    expect([...sc.chunk_sents() as Iterable<unknown>].map(projItem)).toEqual(o.sc.chunk_sents);
    expect([...sc.tagged_chunks(undefined, "pos") as Iterable<unknown>].map(projItem)).toEqual(o.sc.tagged_chunks_pos);
    expect([...sc.tagged_chunks(undefined, "sem") as Iterable<unknown>].map(projItem)).toEqual(o.sc.tagged_chunks_sem);
    expect([...sc.tagged_chunks(undefined, "both") as Iterable<unknown>].map(projItem)).toEqual(o.sc.tagged_chunks_both);
    expect([...sc.tagged_sents(undefined, "pos") as Iterable<unknown>].map(projItem)).toEqual(o.sc.tagged_sents_pos);
    expect([...sc.tagged_sents(undefined, "sem") as Iterable<unknown>].map(projItem)).toEqual(o.sc.tagged_sents_sem);
    expect([...sc.tagged_sents(undefined, "both") as Iterable<unknown>].map(projItem)).toEqual(o.sc.tagged_sents_both);
    expect([...sc2.words() as Iterable<string>]).toEqual(o.sc.words_sem2);
    expect([...sc2.chunks() as Iterable<unknown>].map(projItem)).toEqual(o.sc.chunks_sem2);
    expect(err(() => [...sc2.sents() as Iterable<unknown>].map(projItem))).toEqual(o.sc.sents_sem2);
    expect(err(() => [...sc2.chunk_sents() as Iterable<unknown>].map(projItem))).toEqual(o.sc.chunk_sents_sem2);
    expect((sc.xml("sem1.xml") as any).tag).toEqual(o.sc.xml_tag);
  });

  test("SemcorCorpusReader lazy=False TypeError quirk", () => {
    const scEager = new SemcorCorpusReader(
      new FileSystemPathPointer(join(ROOT, "semcor")), "sem1\\.xml", FakeWN, false);
    expect(err(() => scEager.words())).toEqual(o.sc.eager.words);
    expect(err(() => scEager.sents())).toEqual(o.sc.eager.sents);
    expect(err(() => scEager.chunks())).toEqual(o.sc.eager.chunks);
    expect(err(() => scEager.chunk_sents())).toEqual(o.sc.eager.chunk_sents);
    expect(err(() => scEager.tagged_chunks())).toEqual(o.sc.eager.tagged_chunks);
    expect(err(() => scEager.tagged_sents())).toEqual(o.sc.eager.tagged_sents);
  });

  test("SensevalCorpusReader fileids/instances/_entry", () => {
    const se = new SensevalCorpusReader(
      new FileSystemPathPointer(join(ROOT, "senseval")), ".*\\.pos");
    const projS = (i: any) => ({
      word: i.word,
      position: i.position,
      context: i.context.map((x: any) => (Array.isArray(x) ? [...x] : x)),
      senses: [...i.senses],
      repr: i.repr(),
    });
    expect(se.fileids()).toEqual(o.se.fileids);
    expect([...se.instances() as Iterable<any>].map(projS)).toEqual(o.se.instances);
    expect([...se.instances("hard.pos") as Iterable<any>].map(projS)).toEqual(o.se.instances_fid);
    const doc = parseXmlString(
      "<corpus><lexelt item='x.y'><instance id='i1'>" +
      "<answer senseid='S1'/><context>" +
      "<wf pos='NN'>a</wf><wf pos='VB'>b</wf></context></instance>" +
      "</lexelt></corpus>");
    expect(se._entry(doc).map(([s, c]: [any, any]) => [s, c.map((w: any) => [...w])])).toEqual(o.se.entry);
  });

  test("RTECorpusReader fileids/pairs/words/norm", () => {
    const rt = new RTECorpusReader(
      new FileSystemPathPointer(join(ROOT, "rte")), ".*\\.xml");
    const projP = (p: any) => ({
      challenge: p.challenge, id: p.id, gid: p.gid, text: p.text, hyp: p.hyp,
      value: p.value, task: p.task, length: p.length, repr: p.repr(),
    });
    expect(rt.fileids()).toEqual(o.rt.fileids);
    expect([...rt.pairs(rt.fileids()) as Iterable<any>].map(projP)).toEqual(o.rt.pairs);
    expect([...rt.pairs("rte1_dev.xml") as Iterable<any>].map(projP)).toEqual(o.rt.pairs_dev);
    expect([...rt.pairs(["rte1_dev.xml", "rte3_test.xml"]) as Iterable<any>].map(projP)).toEqual(o.rt.pairs_both);
    expect((rt.xml("rte1_dev.xml") as any).tag).toEqual(o.rt.xml_tag);
    expect(Object.fromEntries((rt.xml("rte1_dev.xml") as any).attrib)).toEqual(o.rt.xml_attrib);
    expect(rt.words("rte1_dev.xml")).toEqual(o.rt.words);
    expect(err(() => rt.xml())).toEqual(o.rt.xml_none);
    const norms = ["TRUE", "FALSE", "yes", "No", "maybe"].map((v) => err(() => norm(v)));
    expect(norms).toEqual(o.rt.norm);
  });
});
